function placeCorrect(correct, distractors, correctIndex) {
  const options = [...distractors];
  options.splice(correctIndex, 0, correct);
  return options;
}

const capitalize = (value) => value.charAt(0).toUpperCase() + value.slice(1);

const workStages = [
  "planning review",
  "installation inspection",
  "pre-energization check",
  "functional test",
  "commissioning review",
  "deficiency investigation",
  "maintenance inspection",
  "return-to-service check",
];

function rewriteQuestion(question, focus, itemIndex, focusCycle) {
  const variant = (question.bankItemNumber + itemIndex) % 12;
  const stage = workStages[focusCycle % workStages.length];
  const diagramLead = question.diagramId
    ? [
        `Use the conceptual diagram for ${focus.label} with the field observations. `,
        `Refer to the conceptual diagram of ${focus.label} before choosing the next action. `,
        `The conceptual diagram shows the intended ${focus.label} relationship. `,
        `Read the ${focus.label} conceptual diagram together with the recorded measurements. `,
        `The conceptual diagram identifies the main parts of ${focus.label}. `,
        `Trace ${focus.label} on the conceptual diagram before evaluating the symptom. `,
        `Compare the field condition with the conceptual diagram for ${focus.label}. `,
        `The conceptual diagram provides a reference for checking ${focus.label}. `,
        `Use the operating path in the conceptual diagram to assess ${focus.label}. `,
        `Start with the ${focus.label} relationship shown in the conceptual diagram. `,
        `The conceptual diagram clarifies how ${focus.label} should be evaluated. `,
        `Review the conceptual diagram and then examine the evidence for ${focus.label}. `,
      ][variant]
    : "";
  let stem;
  let correct;
  if (question.questionType === "foundation") {
    const stems = [
      `${diagramLead}At the ${stage} for ${focus.scenario}, which statement best explains the purpose of ${focus.label}?`,
      `${diagramLead}Why must ${focus.label} be confirmed during the ${stage} when ${focus.scenario}?`,
      `${diagramLead}A crew is preparing for ${focus.scenario}. Which principle about ${focus.label} should govern the ${stage}?`,
      `${diagramLead}Which statement connects ${focus.label} to safe operation during ${focus.scenario} at the ${stage}?`,
      `${diagramLead}The ${stage} has reached ${focus.label} while ${focus.scenario}. What technical relationship matters most?`,
      `${diagramLead}For ${focus.scenario}, what is the best reason to include ${focus.label} in the ${stage}?`,
      `${diagramLead}A new electrician asks what must be understood about ${focus.label} before ${focus.scenario}. Which answer is sound?`,
      `${diagramLead}During a ${stage}, which description of ${focus.label} is technically defensible for ${focus.scenario}?`,
      `${diagramLead}What consequence is ${focus.label} intended to control when ${focus.scenario} reaches the ${stage}?`,
      `${diagramLead}Which underlying principle should be documented for ${focus.label} at the ${stage} of ${focus.scenario}?`,
      `${diagramLead}The job plan calls for ${focus.scenario}. How should the crew understand ${focus.label} before work proceeds?`,
      `${diagramLead}Which explanation would justify checking ${focus.label} as part of the ${stage} for ${focus.scenario}?`,
    ];
    stem = stems[variant];
    correct = focus.principle;
  } else if (question.questionType === "applied_scenario") {
    const stems = [
      `${diagramLead}During the ${stage} for ${focus.scenario}, ${focus.symptom}. Which action uses the most relevant evidence?`,
      `${diagramLead}The crew is ${focus.scenario}. Before accepting ${focus.label} at the ${stage}, what should be compared?`,
      `${diagramLead}${capitalize(focus.symptom)} while ${focus.scenario}. What is the most defensible action at the ${stage}?`,
      `${diagramLead}An electrician must decide whether ${focus.label} is acceptable during ${focus.scenario}. Which evidence should control the ${stage}?`,
      `${diagramLead}At the ${stage}, a concern about ${focus.label} arises while ${focus.scenario}. Which response best tests the concern?`,
      `${diagramLead}The ${stage} for ${focus.scenario} finds that ${focus.symptom}. What should the crew verify before proceeding?`,
      `${diagramLead}While ${focus.scenario}, the recorded result for ${focus.label} is questioned. Which comparison would resolve it at the ${stage}?`,
      `${diagramLead}A supervisor pauses ${focus.scenario} because ${focus.symptom}. Which action supports an evidence-based decision?`,
      `${diagramLead}Which field check would give the strongest basis for accepting ${focus.label} during the ${stage} of ${focus.scenario}?`,
      `${diagramLead}The approved plan and the field condition may disagree while ${focus.scenario}. What should be examined for ${focus.label}?`,
      `${diagramLead}Before signing off the ${stage} for ${focus.scenario}, how should the electrician address ${focus.symptom}?`,
      `${diagramLead}A result involving ${focus.label} appears abnormal during ${focus.scenario}. Which action should precede acceptance?`,
    ];
    stem = stems[variant];
    correct = `Compare ${focus.evidence} with the approved design and the result required at this ${stage}.`;
  } else {
    const stems = [
      `${diagramLead}After ${focus.scenario}, ${focus.symptom}. What should be checked first during the ${stage} to isolate the cause?`,
      `${diagramLead}A fault involving ${focus.label} appears while ${focus.scenario}. Which ${stage} step best separates cause from symptom?`,
      `${diagramLead}${capitalize(focus.symptom)} after ${focus.scenario}. Which test belongs before adjustment or replacement at the ${stage}?`,
      `${diagramLead}The maintenance history shows a recurring problem with ${focus.label}. Which ${stage} action would produce the strongest diagnosis?`,
      `${diagramLead}During ${focus.scenario}, the fault persists and ${focus.symptom}. Where should the ${stage} begin?`,
      `${diagramLead}The ${stage} for ${focus.scenario} must distinguish a control problem from an equipment problem. What should be tested?`,
      `${diagramLead}A previous repair did not correct ${focus.symptom}. Which check should now lead the ${stage} for ${focus.label}?`,
      `${diagramLead}While ${focus.scenario}, the observed symptom could have more than one cause. Which diagnostic step is most discriminating?`,
      `${diagramLead}The electrician must reproduce a fault with ${focus.label} safely. Which ${stage} measurement should come first?`,
      `${diagramLead}${capitalize(focus.symptom)} during ${focus.scenario}. Which test would rule in or rule out the likely cause?`,
      `${diagramLead}Before replacing a component associated with ${focus.label}, what should the electrician establish at the ${stage}?`,
      `${diagramLead}A return visit finds the same issue after ${focus.scenario}. Which evidence should drive the next troubleshooting step?`,
    ];
    stem = stems[variant];
    correct = `Test ${focus.check} under a known condition, compare the result with approved information, and correct only the verified cause.`;
  }

  const distractorLibrary = [
    `Treat ${focus.symptom} as proof that ${focus.label} is defective, then replace the most accessible related component.`,
    `Use one unloaded reading to accept ${focus.label} without comparing it with ${focus.evidence}.`,
    `Increase an adjustable value related to ${focus.label} until ${focus.symptom} disappears, then record the change as acceptable.`,
    `Repeat an arrangement from a different ${focus.label} job without checking the present source, load, or equipment data.`,
    `Rely on the nameplate alone and omit the field measurement of ${focus.evidence} needed for ${focus.label}.`,
    `Bypass a permissive or protective input associated with ${focus.label} and accept normal output as the final test.`,
    `Change the component associated with ${focus.label} and its controlling setting together to return the system quickly.`,
    `Confirm only that the equipment energizes, because normal operation is assumed to prove ${focus.label}.`,
    `Inspect the downstream load first and defer checking ${focus.check} unless the ${focus.label} fault becomes permanent.`,
    `Compare ${focus.label} with an adjacent circuit even though its load, settings, and operating state differ.`,
    `Clear the ${focus.label} indication, re-energize repeatedly, and investigate only if the protective device operates again.`,
    `Document ${focus.symptom} as the cause and close the ${stage} without checking ${focus.check}.`,
  ];
  const distractors = [0, 4, 8].map(
    (offset) => distractorLibrary[(variant + focusCycle + offset) % distractorLibrary.length],
  );
  const explanationLead = [
    focus.principle,
    `The decision turns on ${focus.evidence}, because those observations show whether ${focus.label} is performing as intended.`,
    `${capitalize(focus.symptom)} must be traced through ${focus.check} before an adjustment is justified.`,
    `Acceptance at the ${stage} requires ${focus.evidence}, not an assumption based on appearance or energization alone.`,
    `For ${focus.label}, the safest diagnosis links the observed symptom to ${focus.check} and compares the result with the approved operating condition.`,
    `${capitalize(focus.principle)} The ${stage} should leave a repeatable record of the confirming measurements.`,
    `For ${focus.label}, the field observation is only a symptom; ${focus.evidence} identifies the actual cause.`,
    `A defensible ${focus.label} ${stage} separates measurement, comparison, and correction instead of changing several variables together.`,
    `For ${focus.label}, the approved design and ${focus.evidence} establish the acceptance basis.`,
    `For ${focus.label}, the first useful test evaluates ${focus.check} under a known operating condition.`,
    `Safe return to service depends on proving ${focus.label} with ${focus.evidence}.`,
    `${capitalize(focus.symptom)} does not identify a cause by itself; the electrician must verify ${focus.check}.`,
  ][variant];
  return {
    ...question,
    topic: focus.label,
    question: stem,
    options: placeCorrect(correct, distractors, question.correctIndex),
    explanation: `${explanationLead} The confirming evidence is ${focus.evidence}. If it is overlooked, ${focus.risk}.`,
    steps: null,
    tip: null,
  };
}

for (const batchName of ["b", "c"]) {
  const path = resolve(root, `content/309a/questions/batch-${batchName}.json`);
  const document = JSON.parse(readFileSync(path, "utf8"));
  document.bankVersionKey = versionKey;
  document.questionDefaults.bankVersionKey = versionKey;
  const taskPositions = new Map();
  document.questions = document.questions.map((question) => {
    if (question.isCalc === "yes") return question;
    const position = taskPositions.get(question.taskCode) ?? 0;
    taskPositions.set(question.taskCode, position + 1);
    const focuses = FOCUS[question.taskCode];
    if (!focuses?.length) throw new Error(`No focus library for ${question.taskCode}`);
    return rewriteQuestion(
      question,
      focuses[position % focuses.length],
      position,
      Math.floor(position / focuses.length),
    );
  });
  writeFileSync(path, `${JSON.stringify(document, null, 2)}\n`);
}

console.log("Rewrote all 225 non-calculation questions in 309A batches B and C with task-specific scenarios and explanations.");
